{
  "process": "Each row represents a defendant who was arrested and then screened by the COMPAS algorithm. The sequence of events is: arrest → COMPAS screening (recording charge, demographics, prior juvenile and adult offenses) → release or detention → two‑year follow‑up window during which any new offense is recorded → determination of whether the defendant recidivated within two years.",
  "target_known_at": "the end of the two‑year follow‑up period when it is observed whether a new offense occurred.",
  "prediction_point": "immediately after the COMPAS screening, i.e., right after arrest but before any future events in the follow‑up window.",
  "columns": [
    {
      "name": "c_charge_desc",
      "event": "recording of the defendant's current charge at COMPAS screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "age_cat",
      "event": "derivation of age category from defendant's age at screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "sex",
      "event": "recording of defendant's sex at screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "r_charge_desc",
      "event": "recording of the charge associated with any recidivism offense (if any) during the two‑year follow‑up",
      "verdict": "UNAVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "race",
      "event": "recording of defendant's race/ethnicity at screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "juv_fel_count",
      "event": "count of juvenile felony offenses prior to screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "c_charge_degree",
      "event": "recording of the degree (felony/misdemeanor) of the current charge at screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "priors_count",
      "event": "count of prior adult offenses before screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "r_charge_degree",
      "event": "recording of the degree of the recidivism charge (if any) during follow‑up",
      "verdict": "UNAVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "juv_misd_count",
      "event": "count of juvenile misdemeanor offenses prior to screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "r_offense_date",
      "event": "date of the recidivism offense (if any) during the two‑year follow‑up",
      "verdict": "UNAVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "age",
