      "confidence": 0.95
    },
    {
      "name": "juv_other_count",
      "event": "count of other juvenile offenses (e.g., status offenses) prior to screening",
      "verdict": "AVAILABLE",
      "confidence": 0.99
    },
    {
      "name": "r_days_from_arrest",
